import {menuImages} from './navigation-art.js';
import {services,mainNavigation} from './navigation-data.js?v=menu-no-pow-ai';
const header=document.querySelector('.pow-header'),mount=document.getElementById('header-navigation');
const link=item=>`<a href="${item.href}">${item.title}</a>`;
mount.innerHTML=`<nav id="pow-navigation" aria-label="Điều hướng chính">${link(mainNavigation[0])}<div class="services-disclosure"><button type="button" class="services-trigger" aria-expanded="false" aria-controls="services-mega">Dịch vụ</button><div id="services-mega" hidden><div class="mega-heading"><span>DỊCH VỤ POWAI</span><a href="/#universe-map">Khám phá giải pháp →</a></div><div class="category-index">${services.map((g,i)=>`<button type="button" class="category-choice" data-group="${i}" aria-expanded="false" aria-controls="category-detail"><span>${g.title}</span><span aria-hidden="true">→</span></button>`).join('')}</div><div id="category-detail" hidden></div></div></div>${mainNavigation.slice(1).map(link).join('')}</nav>`;
const trigger=header.querySelector('.services-trigger'),panel=document.getElementById('services-mega'),disclosure=header.querySelector('.services-disclosure'),mobile=header.querySelector('.mobile-nav-toggle'),index=panel.querySelector('.category-index'),detail=document.getElementById('category-detail');
const compact=matchMedia('(max-width: 1100px)');let timer,hoverOpened=false,selected=-1;
function showIndex(focus=false){const previous=selected;selected=-1;index.hidden=false;detail.hidden=true;panel.classList.remove('showing-category');panel.querySelectorAll('.category-choice').forEach(b=>b.setAttribute('aria-expanded','false'));if(focus&&previous>=0)index.children[previous].focus();}
function showCategory(i){selected=i;const g=services[i];index.hidden=true;detail.hidden=false;panel.classList.add('showing-category');index.children[i].setAttribute('aria-expanded','true');detail.innerHTML=`<button type="button" class="category-back">← Tất cả danh mục</button><div class="category-body"><div class="category-services"><h2 tabindex="-1">${g.title}</h2><ul>${g.children.map(c=>`<li><a href="${c.href}"><span>${c.title}</span><span aria-hidden="true">↗</span></a></li>`).join('')}</ul><a class="category-all" href="${g.href}">Khám phá ${g.title} →</a></div><figure class="category-art"><img src="${menuImages[g.slug]}" alt="Minh họa ${g.title}" width="360" height="220"><figcaption>${g.title}<small>POWAI / MARKETING × TECHNOLOGY</small></figcaption></figure></div>`;detail.querySelector('.category-back').onclick=()=>showIndex(true);detail.querySelector('h2').focus();panel.scrollTop=0;}
function setServices(open){clearTimeout(timer);panel.hidden=!open;trigger.setAttribute('aria-expanded',String(open));if(!open){hoverOpened=false;showIndex();}}
function setMobile(open){header.classList.toggle('mobile-nav-open',open);mobile.setAttribute('aria-expanded',String(open));mobile.setAttribute('aria-label',open?'Đóng menu':'Mở menu');if(!open)setServices(false);}
index.addEventListener('click',e=>{const b=e.target.closest('[data-group]');if(b)showCategory(Number(b.dataset.group));});
trigger.addEventListener('click',()=>{if(hoverOpened){hoverOpened=false;return;}setServices(panel.hidden);});
mobile.addEventListener('click',()=>setMobile(mobile.getAttribute('aria-expanded')!=='true'));
disclosure.addEventListener('pointerenter',e=>{if(!compact.matches&&e.pointerType==='mouse'){clearTimeout(timer);if(panel.hidden){setServices(true);hoverOpened=true;}}});
disclosure.addEventListener('pointerleave',e=>{if(!compact.matches&&e.pointerType==='mouse')timer=setTimeout(()=>{if(!disclosure.contains(document.activeElement))setServices(false);},180);});
header.addEventListener('keydown',event=>{if(event.key==='Escape'){if(!panel.hidden&&selected>=0)showIndex(true);else if(!panel.hidden){setServices(false);trigger.focus();}else if(compact.matches&&mobile.getAttribute('aria-expanded')==='true'){setMobile(false);mobile.focus();}event.preventDefault();}if(event.key==='ArrowDown'&&event.target===trigger){setServices(true);index.querySelector('button').focus();event.preventDefault();}});
header.addEventListener('focusout',()=>setTimeout(()=>{if(!header.contains(document.activeElement)){setServices(false);if(compact.matches)setMobile(false);}},0));
document.addEventListener('pointerdown',event=>{if(!header.contains(event.target)){setServices(false);setMobile(false);}});
header.addEventListener('click',event=>{const a=event.target.closest('a');if(!a)return;const url=new URL(a.href,location.href);if(url.origin===location.origin&&url.pathname==='/'&&url.hash){const destination=document.querySelector(url.hash);if(destination){event.preventDefault();setMobile(false);setServices(false);history.pushState(null,'',url.hash);destination.scrollIntoView({behavior:'instant',block:'start'});}}});
compact.addEventListener('change',()=>setMobile(false));
